#!/usr/bin/env bash
# AT-M0-04 (M0.T04; selection §9 S-3, S-4): `make m0-gate AT=AT-M0-04`.
# Runs M0.T04 steps 8–14 through tools/bench.sh (Release build, one-GPU-job lock) plus the XCUITest
# SpikeRestartTests, then evaluates the five pass conditions into build/at/AT-M0-04/result.json.
# Env: FIXTURES (default fixtures; falls back to build/fixtures-t04 generated by the fixture scripts when the
#      submodule lacks prompts/ or images/ocr/), SKIP_BENCH=1 (evaluate existing raw runs only),
#      SKIP_UITEST=1, RUNS (default 20), LOAD_RUNS (default 10), RESTART_RUNS (default 10).
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
cd "$ROOT"
OUT=build/at/AT-M0-04
mkdir -p "$OUT" build/perf/raw
DATE="$(date +%Y-%m-%d)"
LOG="$OUT/$DATE.log"
exec > >(tee -a "$LOG") 2>&1
echo "== AT-M0-04 $(date -u +%FT%TZ) commit $(git rev-parse --short HEAD)"
RUNS="${RUNS:-20}"; LOAD_RUNS="${LOAD_RUNS:-10}"; RESTART_RUNS="${RESTART_RUNS:-10}"
export REPLACE=1

FIXTURES="${FIXTURES:-fixtures}"
if [ ! -f "$FIXTURES/prompts/bench-300tok.txt" ] || [ ! -f "$FIXTURES/images/ocr/answers.jsonl" ]; then
  echo "[fix] $FIXTURES lacks the T04 prompts/ocr fixtures; generating them into build/fixtures-t04"
  python3 -I tools/fixtures/make-bench-prompts.py --out build/fixtures-t04/prompts
  tools/.venv/bin/python -I tools/fixtures/make-ocr.py --out build/fixtures-t04/images/ocr
  mkdir -p build/fixtures-t04/stub-models/tiny-gguf
  [ -f build/fixtures-t04/stub-models/tiny-gguf/tiny.gguf ] || cp "$FIXTURES/stub-models/tiny-gguf/tiny.gguf" build/fixtures-t04/stub-models/tiny-gguf/ 2>/dev/null || true
  FIXTURES=build/fixtures-t04
fi
export FIXTURES
TINY="$ROOT/$FIXTURES/stub-models/tiny-gguf/tiny.gguf"
APP=build/dd-bench/Build/Products/Release/AntiChat.app
BIN="$APP/Contents/MacOS/AntiChat"

if [ "${SKIP_BENCH:-0}" != 1 ] && [ "${SKIP_MATRIX:-0}" != 1 ]; then
  # Step 8 run matrix (first call builds the Release app once; the rest reuse it).
  NO_BUILD=0 tools/bench.sh chat --model chat-0.8b --tier-cap T0 --runs "$RUNS" --ctx 1k
  export NO_BUILD=1
  tools/bench.sh chat --model chat-0.8b --tier-cap T0 --runs "$RUNS" --ctx 4k
  tools/bench.sh chat --model chat-0.8b --tier-cap T1 --runs "$RUNS" --ctx 1k
  tools/bench.sh chat --model chat-0.8b --tier-cap T1 --runs "$RUNS" --ctx 4k
  tools/bench.sh chat --model chat-9b-q4 --tier-cap T1 --runs "$RUNS" --ctx 1k
  tools/bench.sh chat --model chat-9b-q4 --tier-cap T1 --runs "$RUNS" --ctx 4k
  tools/bench.sh chat --model chat-35b-q4 --tier-cap T3-48 --runs "$RUNS" --ctx 1k
  tools/bench.sh chat --model chat-35b-q4 --tier-cap T3-48 --runs "$RUNS" --ctx 4k
  # M1 cold load: no `sudo purge` without P-ADMIN → [WARM-CACHE] (M0.T04 fallback).
  for spec in "chat-0.8b T0" "chat-0.8b T1" "chat-9b-q4 T1" "chat-35b-q4 T3-48"; do
    set -- $spec
    tools/bench.sh load --model "$1" --tier-cap "$2" --runs "$LOAD_RUNS"
  done
  # Step 9 S-3 overhead: in-process baseline, and the XPC fallback batch window for comparison.
  NO_BUILD=0 tools/bench.sh inproc --model chat-9b-q4 --tier-cap T1 --runs "$RUNS"
  BENCH_TAG=b33x16 tools/bench.sh chat --model chat-9b-q4 --tier-cap T1 --runs "$RUNS" --ctx 1k --batch 33:16 --label xpc33
fi
if [ "${SKIP_BENCH:-0}" != 1 ]; then
  export NO_BUILD=1
  # Step 10 crash restart (llama tiny-gguf so the orphan watchdog is exercised).
  # launchd throttles the relaunch of an XPC service that crashed < 10 s after it started (measured: ≈ 10.07 s
  # with uptime < 10 s, ≈ 0.03 s with uptime ≥ 12 s; S-3 report). The gate measures the steady state (helper up
  # ≥ 11 s, the normal case); the throttled case is recorded separately and not gated.
  tools/bench.sh restart --model "gguf:$TINY" --runs "$RESTART_RUNS" --alive-before-kill 11
  BENCH_TAG=mlx tools/bench.sh restart --model chat-0.8b --runs 3 --alive-before-kill 11 --label mlx
  BENCH_TAG=throttle tools/bench.sh restart --model "gguf:$TINY" --runs 3 --label throttle
  # Step 13 K-NEW-MOD-5 family support.
  IMG="$ROOT/$FIXTURES/images/ocr/doc-00.png"
  for m in chat-g12 chat-lfm3 chat-g26 chat-9b-q8; do
    lockf /tmp/antichat-gpu.lock "$BIN" -Bench family --model "$m" --fixtures "$FIXTURES" --raw "build/perf/raw/family-$m.jsonl" || true
  done
  lockf /tmp/antichat-gpu.lock "$BIN" -Bench family --model chat-35b-q4+vision --image "$IMG" --fixtures "$FIXTURES" --raw build/perf/raw/family-chat-35b-q4-vision.jsonl || true
  lockf /tmp/antichat-gpu.lock "$BIN" -Bench family --model chat-g12 --image "$IMG" --fixtures "$FIXTURES" --raw build/perf/raw/family-chat-g12-vision.jsonl || true
fi

# Step 11: no TCP listener (D-10). Keep llama-server up with the tiny GGUF and inspect every llama pid.
"$BIN" -Bench family --model "gguf:$TINY" --hold 8 --raw build/perf/raw/family-tiny-hold.jsonl &
HOLD=$!
for _ in $(seq 1 100); do
  [ -n "$(pgrep -f "$ROOT/$APP/Contents/Helpers/llama-server --host 127.0.0.1" || true)" ] && break
  sleep 0.1
done
# Anchor on this checkout's absolute app path so a llama-server from another worktree's bench is not inspected.
PIDS="$(pgrep -f "$ROOT/$APP/Contents/Helpers/llama-server" | paste -sd, - || true)"
{
  echo "# llama-server pids: $PIDS"
  ps -o pid,ppid,pgid,args -p "${PIDS:-0}" | cut -c1-260 || true
  echo "# lsof -nP -a -p <pids> -iTCP -sTCP:LISTEN"
  lsof -nP -a -p "${PIDS:-0}" -iTCP -sTCP:LISTEN || true
  echo "# unix sockets"
  lsof -nP -a -p "${PIDS:-0}" -U | grep -i sock || true
  PORT="$(lsof -nP -a -p "${PIDS:-0}" -iTCP -sTCP:LISTEN 2>/dev/null | awk 'NR==2{print $9}' | sed 's/.*://')"
  if [ -n "$PORT" ]; then
    echo "# keyless request to the child port $PORT (must be 401)"
    curl -s -o /dev/null -w '%{http_code}\n' "http://127.0.0.1:$PORT/v1/models" || true
  fi
  echo "# api key visible in ps args? (must be 0)"
  ps -o args -p "${PIDS:-0}" | grep -c -- '--api-key' || true
} > "$OUT/lsof.txt" 2>&1
wait "$HOLD" || true
cat "$OUT/lsof.txt"

# Step 10 UI side: XCUITest (Debug; hardened runtime off for the ad-hoc dev build, A-M0-09).
UITEST=skipped
if [ "${SKIP_UITEST:-0}" = 1 ] && grep -q "Timed out while enabling automation mode" "$OUT/uitest.log" 2>/dev/null; then
  UITEST=blocked-automation-mode   # from the previous run's log (Q-015)
fi
if [ "${SKIP_UITEST:-0}" != 1 ]; then
  if xcodebuild test -workspace AntiChat.xcworkspace -scheme AntiChat-Debug -only-testing:AntiChatUITests/SpikeRestartTests \
      -derivedDataPath build/dd -disableAutomaticPackageResolution -packageAuthorizationProvider netrc \
      CODE_SIGN_IDENTITY=- ENABLE_HARDENED_RUNTIME=NO > "$OUT/uitest.log" 2>&1; then
    UITEST=pass
  else
    UITEST=fail
    # Q-015: without an authorised automation mode the runner cannot start; use the in-app probe instead.
    grep -q "Timed out while enabling automation mode" "$OUT/uitest.log" && UITEST=blocked-automation-mode
  fi
  grep -E "SPIKE|error:|Test Case|passed|failed|automation" "$OUT/uitest.log" | tail -20 || true
fi
# Fallback UI-alive evidence (Q-015): App/AntiChat/SpikeProbe.swift, 3 runs, real SpikeChatModel + window.
if [ "$UITEST" != pass ] && [ "${SKIP_BENCH:-0}" != 1 ]; then
  for n in 1 2 3; do
    lockf /tmp/antichat-gpu.lock "$BIN" -SpikeUI YES -SpikeProbe "$ROOT/$OUT/ui-probe-$n.json" || true
  done
fi

python3 -I tools/perf/scale.py --report build/perf/report.json $([ "${REPLACE:-0}" = 1 ] && echo --replace) > "$OUT/scale.log" || true

python3 -I - "$OUT" "$UITEST" "$(git rev-parse HEAD)" <<'PY'
import csv, glob, json, os, platform, subprocess, sys
out, uitest, commit = sys.argv[1], sys.argv[2], sys.argv[3]
rep = json.load(open("build/perf/report.json")) if os.path.exists("build/perf/report.json") else {}
checks = []
def add(name, value, bar, ok):
    checks.append({"name": name, "value": value, "bar": bar, "pass": bool(ok)})

# 1. report.json rows
need = [("T0", "chat-0.8b"), ("T1", "chat-0.8b"), ("T1", "chat-9b-q4"), ("T3-48", "chat-35b-q4")]
for tier, model in need:
    for m, n in (("C1", 20), ("C1b", 20), ("C2", 20), ("C4", 20), ("M1", 10), ("R1", 20)):
        v = rep.get(f"m0.{m}.{tier}.{model}")
        add(f"report {m} {tier} {model}", None if not v else {"p50": v["p50"], "p95": v["p95"], "n": v["n"], "nfr_pass": v.get("pass")},
            f"present, n >= {n}", v is not None and v["n"] >= n)
# 2. S-3 overhead + msgs/s
x, ip = rep.get("m0.C2.T1.chat-9b-q4"), rep.get("m0.inproc.C2.T1.chat-9b-q4")
if x and ip:
    ov = (ip["p50"] - x["p50"]) / ip["p50"] * 100
    add("S-3 XPC decode overhead % (p50, chat-9b-q4 T1)", round(ov, 2), "<= 3%", ov <= 3)
else:
    add("S-3 XPC decode overhead %", None, "<= 3%", False)
mm = rep.get("m0.XPCMSG.T1.chat-9b-q4")
add("XPC msgs/s while streaming (chat-9b-q4 T1, p95)", mm and round(mm["p95"], 1), "<= 60", mm is not None and mm["p95"] <= 60)
# 3. restart
rows = []
for f in sorted(glob.glob("build/perf/raw/restart-*.jsonl")):
    rows += [json.loads(l) for l in open(f) if l.strip()]
with open(os.path.join(out, "restart-runs.csv"), "w", newline="") as fh:
    w = csv.writer(fh)
    w.writerow(["model", "run", "killed_pid", "new_pid", "restart_s", "orphan_gone_s", "llama_pids_before", "stream_ended_with"])
    for r in rows:
        w.writerow([r.get("model"), r.get("run"), r.get("killed_pid"), r.get("new_pid"), r.get("restart_s"), r.get("orphan_gone_s"), r.get("llama_pids_before"), r.get("stream_ended_with")])
gg = [r for r in rows if str(r.get("model", "")).startswith("gguf:") and r.get("label", "xpc") == "xpc"]
ok_restart = [r for r in gg if 0 <= r.get("restart_s", -1) <= 5]
add("helper kill -9 -> HelloAck <= 5 s (llama runs)", f"{len(ok_restart)}/{len(gg)} max={max([r.get('restart_s', -1) for r in gg], default=None)}", "10/10", len(gg) >= 10 and len(ok_restart) == len(gg))
orph = [r for r in gg if 0 <= r.get("orphan_gone_s", -1) <= 5]
add("zero orphan llama-server after 5 s", f"{len(orph)}/{len(gg)}", "10/10", len(gg) >= 10 and len(orph) == len(gg))
probes = [json.load(open(f)) for f in sorted(glob.glob(os.path.join(out, "ui-probe-*.json")))]
probe_ok = len(probes) >= 3 and all(p.get("restarted_notice_shown") and p.get("input_after_kill") == "still here"
                                    and 0 <= p.get("worst_main_latency_s", 9) <= 0.1 and p.get("retry_streaming_after_kill_s", -1) > 0 for p in probes)
ui_val = {"xcuitest": uitest, "probe_runs": len(probes), "worst_main_latency_s": max([p.get("worst_main_latency_s", 9) for p in probes], default=None),
          "restarted_notice_shown": [p.get("restarted_notice_shown") for p in probes]}
add("UI alive during helper kill -9 (XCUITest, else SpikeProbe fallback Q-015): no stall > 100 ms, engine.restarted shown, Retry streams",
    ui_val, "pass", uitest == "pass" or (uitest != "fail" and probe_ok))
# 4. lsof
txt = open(os.path.join(out, "lsof.txt")).read()
# No llama-server pid found → lsof ran against pid 0 and printed nothing; that is "not measured", not "empty".
pids_line = next((l for l in txt.splitlines() if l.startswith("# llama-server pids:")), "")
inspected = bool(pids_line.split(":", 1)[-1].strip())
listen = [l for l in txt.splitlines() if "(LISTEN)" in l]
only_loop = all("127.0.0.1:" in l for l in listen)
keyless = [l for l in txt.splitlines() if l.strip() in ("401", "200")]
# The router binds only the unix socket, but each loaded model is a router-spawned child on 127.0.0.1:<port>
# (llama.cpp@620d222 server-models.cpp:59,523). M0.T04's documented fallback (A-M0-08) turns the check into
# "only 127.0.0.1, random port, key required"; the strict result is kept in the value for the record.
add("lsof TCP LISTEN for llama-server: empty, or A-M0-08 fallback (127.0.0.1 only, random port, 401 without key)",
    {"pids_inspected": inspected, "strict_empty": not listen, "listen": listen, "keyless_status": keyless},
    "empty | 127.0.0.1-only + 401", inspected and ((not listen) or (only_loop and keyless == ["401"])))
# 5. S-4 + K-NEW-MOD-5
s4 = open("docs/research/07-spikes/S-4-vmlx.md").read() if os.path.exists("docs/research/07-spikes/S-4-vmlx.md") else ""
add("S-4-vmlx.md has s4_verdict", "s4_verdict" in s4, "present", "s4_verdict:" in s4)
fam = {}
for f in sorted(glob.glob("build/perf/raw/family-*.jsonl")):
    for l in open(f):
        if l.strip():
            r = json.loads(l); fam[os.path.basename(f)] = {k: r.get(k) for k in ("model", "loads", "generates", "vision", "error")}
need_fam = ["family-chat-g12.jsonl", "family-chat-lfm3.jsonl", "family-chat-35b-q4-vision.jsonl"]
add("K-NEW-MOD-5 table complete (g12, lfm3, 35b vision)", fam, "all three rows present", all(k in fam for k in need_fam))

host = {"machine": platform.machine(), "macos": platform.mac_ver()[0],
        "chip": subprocess.run(["sysctl", "-n", "machdep.cpu.brand_string"], capture_output=True, text=True).stdout.strip()}
res = {"at": "AT-M0-04", "pass": all(c["pass"] for c in checks), "checks": checks, "commit": commit, "host": host}
json.dump(res, open(os.path.join(out, "result.json"), "w"), indent=2)
for c in checks:
    print(("[ok]  " if c["pass"] else "[FAIL]") + f" {c['name']}: {c['value']} (bar {c['bar']})")
print("AT-M0-04 pass =", res["pass"])
sys.exit(0 if res["pass"] else 1)
PY
